```python
import os
import uuid
import sqlite3
from flask import (
    Flask, request, redirect, url_for, render_template_string,
    session, send_file, abort, flash
)
from werkzeug.security import generate_password_hash, check_password_hash
from werkzeug.utils import secure_filename
from functools import wraps

# Configuration
UPLOAD_FOLDER = os.path.abspath("./uploads")  # Outside web root
ALLOWED_EXTENSIONS = {'pdf', 'txt'}
DATABASE = './student_portal.db'
SECRET_KEY = os.urandom(32)  # In production, use a fixed secret key from env/config

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
app.config['SECRET_KEY'] = SECRET_KEY
app.config['SESSION_COOKIE_HTTPONLY'] = True
app.config['SESSION_COOKIE_SECURE'] = True  # Requires HTTPS
app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'

# Ensure upload folder exists
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

# Database helpers
def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    with get_db() as db:
        db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS submissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            filename TEXT NOT NULL,
            original_filename TEXT NOT NULL,
            upload_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(user_id) REFERENCES users(id)
        );
        ''')

# Authentication helpers
def login_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user_id' not in session:
            flash("Please log in to access this page.", "warning")
            return redirect(url_for('login'))
        return f(*args, **kwargs)
    return decorated_function

def allowed_file(filename):
    # Check extension only, no user input used for storage filename
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

# Routes

@app.route('/')
def index():
    if 'user_id' in session:
        return redirect(url_for('dashboard'))
    return redirect(url_for('login'))

@app.route('/signup', methods=['GET', 'POST'])
def signup():
    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        password = request.form.get('password', '')
        if not username or not password:
            flash("Username and password are required.", "danger")
            return redirect(url_for('signup'))
        if len(password) < 8:
            flash("Password must be at least 8 characters.", "danger")
            return redirect(url_for('signup'))

        password_hash = generate_password_hash(password)
        try:
            with get_db() as db:
                db.execute(
                    "INSERT INTO users (username, password_hash) VALUES (?, ?)",
                    (username, password_hash)
                )
            flash("Signup successful. Please log in.", "success")
            return redirect(url_for('login'))
        except sqlite3.IntegrityError:
            flash("Username already taken.", "danger")
            return redirect(url_for('signup'))

    # Minimal safe HTML template
    return render_template_string('''
    <h2>Sign Up</h2>
    <form method="post" autocomplete="off">
      <label>Username: <input type="text" name="username" required></label><br>
      <label>Password: <input type="password" name="password" required></label><br>
      <button type="submit">Sign Up</button>
    </form>
    <p>Already have an account? <a href="{{ url_for('login') }}">Log in</a></p>
    ''')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        password = request.form.get('password', '')
        if not username or not password:
            flash("Invalid username or password.", "danger")
            return redirect(url_for('login'))

        with get_db() as db:
            user = db.execute(
                "SELECT * FROM users WHERE username = ?", (username,)
            ).fetchone()

        # Avoid username enumeration by using same message for all failures
        if user and check_password_hash(user['password_hash'], password):
            session.clear()
            session['user_id'] = user['id']
            session['username'] = user['username']
            flash("Logged in successfully.", "success")
            return redirect(url_for('dashboard'))
        else:
            flash("Invalid username or password.", "danger")
            return redirect(url_for('login'))

    return render_template_string('''
    <h2>Log In</h2>
    <form method="post" autocomplete="off">
      <label>Username: <input type="text" name="username" required></label><br>
      <label>Password: <input type="password" name="password" required></label><br>
      <button type="submit">Log In</button>
    </form>
    <p>Don't have an account? <a href="{{ url_for('signup') }}">Sign up</a></p>
    ''')

@app.route('/logout')
@login_required
def logout():
    session.clear()
    flash("You have been logged out.", "info")
    return redirect(url_for('login'))

@app.route('/dashboard')
@login_required
def dashboard():
    user_id = session['user_id']
    with get_db() as db:
        submissions = db.execute(
            "SELECT id, original_filename, upload_time FROM submissions WHERE user_id = ? ORDER BY upload_time DESC",
            (user_id,)
        ).fetchall()

    return render_template_string('''
    <h2>Welcome, {{ username }}</h2>
    <p><a href="{{ url_for('logout') }}">Log out</a></p>

    <h3>Upload Assignment</h3>
    <form method="post" action="{{ url_for('upload') }}" enctype="multipart/form-data">
      <input type="file" name="file" required>
      <button type="submit">Upload</button>
    </form>

    <h3>Your Submissions</h3>
    {% if submissions %}
      <ul>
      {% for sub in submissions %}
        <li>
          {{ sub['original_filename'] }} (uploaded {{ sub['upload_time'] }})
          - <a href="{{ url_for('download', submission_id=sub['id']) }}">Download</a>
        </li>
      {% endfor %}
      </ul>
    {% else %}
      <p>No submissions yet.</p>
    {% endif %}
    ''', username=session['username'], submissions=submissions)

@app.route('/upload', methods=['POST'])
@login_required
def upload():
    if 'file' not in request.files:
        flash("No file part in the request.", "danger")
        return redirect(url_for('dashboard'))

    file = request.files['file']
    if file.filename == '':
        flash("No file selected.", "danger")
        return redirect(url_for('dashboard'))

    if not allowed_file(file.filename):
        flash("File type not allowed. Only PDF and TXT files are accepted.", "danger")
        return redirect(url_for('dashboard'))

    # Generate a secure unique filename (UUID + extension)
    ext = file.filename.rsplit('.', 1)[1].lower()
    unique_filename = f"{uuid.uuid4().hex}.{ext}"

    # Save file outside web root
    file_path = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)
    file.save(file_path)

    # Store metadata in DB
    with get_db() as db:
        db.execute(
            "INSERT INTO submissions (user_id, filename, original_filename) VALUES (?, ?, ?)",
            (session['user_id'], unique_filename, secure_filename(file.filename))
        )

    flash("File uploaded successfully.", "success")
    return redirect(url_for('dashboard'))

@app.route('/download/<int:submission_id>')
@login_required
def download(submission_id):
    user_id = session['user_id']
    with get_db() as db:
        submission = db.execute(
            "SELECT filename, original_filename FROM submissions WHERE id = ? AND user_id = ?",
            (submission_id, user_id)
        ).fetchone()

    if not submission:
        # Do not reveal if submission exists or not
        abort(404)

    file_path = os.path.join(app.config['UPLOAD_FOLDER'], submission['filename'])

    # Check file existence to avoid errors
    if not os.path.isfile(file_path):
        abort(404)

    # Serve file with original filename for download
    return send_file(
        file_path,
        as_attachment=True,
        download_name=submission['original_filename'],
        mimetype='application/octet-stream'
    )

# Run initialization
if __name__ == '__main__':
    init_db()
    app.run(debug=False)  # Debug off for security
```

